import datetime

from ta_moler.events.emssim.genericemssim_lineevent import GenericEMSSIMLineEvent


class DiscoverOperationSucceeded(GenericEMSSIMLineEvent):
    """Discoveroperationsucceeded event class."""

    _re_succeeded_discover_detected = r"Discover Operation SUCCEEDED"

    def __init__(self, connection, till_occurs_times=1, runner=None):
        """
        Event for Discoveroperationsucceeded.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        """
        super(DiscoverOperationSucceeded, self).__init__(
            connection=connection,
            runner=runner,
            till_occurs_times=till_occurs_times,
            detect_patterns=[
                DiscoverOperationSucceeded._re_succeeded_discover_detected,
            ],
            match="any",
        )
        self.process_full_lines_only = True


